import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{Bo as i,Fo as a,Ho as o,Io as s,Lo as c,Po as l,Ro as u,Vo as d,zo as f}from"./chunks/assets.CUKu7Ix7.js";var p=JSON.parse(`{"title":"MySQL概述","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/basics/overview.md","filePath":"mysql/basics/overview.md"}`),m={name:`mysql/basics/overview.md`};function h(r,p,m,h,g,_){return n(),t(`div`,null,[...p[0]||=[e(`<h1 id="mysql概述" tabindex="-1">MySQL概述 <a class="header-anchor" href="#mysql概述" aria-label="Permalink to “MySQL概述”">​</a></h1><p><img src="`+o+`" alt="image.png" width="251" height="156"></p><p>官网：<a href="https://dev" target="_blank" rel="noreferrer">https://dev</a>.mysql.com/</p><p><strong>MySQL官方提供了两个版本：</strong></p><ul><li><p>商业版本（MySQL Enterprise Edition）</p><ul><li>该版本是收费的，我们可以使用30天。 官方会提供对应的技术支持。</li></ul></li><li><p>社区版本（MySQL Community Server）</p><ul><li>该版本是免费的，但是MySQL不会提供任何的技术支持。</li></ul></li></ul><p>本课程，采用的是MySQL的社区版本（8.0.34）</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><p>官网下载地址：<a href="https://downloads.mysql.com/archives/community/" target="_blank" rel="noreferrer">https://downloads.mysql.com/archives/community/</a></p><p><img src="`+d+`" alt="image.png" width="1102" height="890"></p><h2 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to “连接”">​</a></h2><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>MySQL服务器启动完毕后，然后再使用如下指令，来连接MySQL服务器：</p><div class="language-Java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u用户名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p密码 [</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h数据库服务器的IP地址 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P端口号]</span></span></code></pre></div><ul><li><p>-h 参数不加，默认连接的是本地 127.0.0.1 的MySQL服务器</p></li><li><p>-P 参数不加，默认连接的端口号是 3306</p></li></ul><p><strong>上述指令，可以有两种形式：</strong></p><ul><li>密码直接在-p参数之后直接指定 （这种方式不安全，密码直接以明文形式出现在命令行）</li></ul><p><img src="`+i+`" alt="image.png" width="1371" height="425"></p><ul><li>密码在-p回车之后，在命令行中输入密码，然后回车</li></ul><p><img src="`+f+`" alt="image.png" width="1370" height="547"></p><h3 id="企业使用方式-了解" tabindex="-1">企业使用方式(了解) <a class="header-anchor" href="#企业使用方式-了解" aria-label="Permalink to “企业使用方式(了解)”">​</a></h3><p>上述的MySQL服务器我们是安装在本地的，这个仅仅是在我们学习阶段，在真实的企业开发中，MySQL数据库服务器是不会在我们本地安装的，是在公司的服务器上安装的，而服务器还需要放置在专门的IDC机房中的，IDC机房呢，就需要保证恒温、恒湿、恒压，而且还要保证网络、电源的可靠性(备用电源及网络)。</p><p><img src="`+u+`" alt="image.png" width="1373" height="333"></p><p>那我们要想使用服务器上的这台MySQL服务器，就需要在我们的电脑上去远程连接这台MySQL 。 而服务器上安装的MySQL数据库呢，并不是你一个人在访问，我们项目组的其他开发人员也是需要访问这台MySQL的。</p><p><img src="`+c+`" alt="image.png" width="1368" height="338"></p><p>接下来，就来演示一下，通过MySQL的客户端命令行，如何来连接服务器上部署的MySQL ：</p><div class="language-Java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql [</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h数据库服务器的IP地址 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P端口号] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u用户名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p密码</span></span></code></pre></div><p><img src="`+s+`" alt="image.png" width="1371" height="546"></p><h2 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to “数据模型”">​</a></h2><p>介绍完了Mysql数据库的安装配置之后，接下来我们再来聊一聊Mysql当中的数据模型。学完了这一小节之后，我们就能够知道在Mysql数据库当中到底是如何来存储和管理数据的。</p><p>在介绍 Mysql的数据模型之前，需要先了解一个概念：关系型数据库。</p><h3 id="关系型数据库-rdbms" tabindex="-1"><strong>关系型数据库**</strong>（RDBMS）** <a class="header-anchor" href="#关系型数据库-rdbms" aria-label="Permalink to “关系型数据库**（RDBMS）**”">​</a></h3><p>概念：建立在关系模型基础上，由多张相互连接的<strong>二维表</strong>组成的数据库。而所谓二维表，指的是由行和列组成的表，如下图：</p><p><img src="`+a+`" alt="image.png" width="1127" height="296"></p><p>二维表的优点：</p><ul><li><p>使用表存储数据，格式统一，便于维护</p></li><li><p>使用SQL语言操作，标准统一，使用方便，可用于复杂查询</p></li></ul><p>我们之前提到的MySQL、Oracle、DB2、SQLServer这些都是属于关系型数据库，里面都是基于二维表存储数据的。</p><p><strong>结论：</strong>基于二维表存储数据的数据库就成为关系型数据库，不是基于二维表存储数据的数据库，就是非关系型数据库（比如大家后面要学习的Redis，就属于非关系型数据库）。</p><h3 id="数据模型-1" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型-1" aria-label="Permalink to “数据模型”">​</a></h3><p>介绍完了关系型数据库之后，接下来我们再来看一看在Mysql数据库当中到底是如何来存储数据的，也就是Mysql 的数据模型。</p><p>MySQL是关系型数据库，是基于二维表进行数据存储的，具体的结构图下:</p><p><img src="`+l+`" alt="image.png" width="1540" height="582"></p><ul><li><p>通过MySQL客户端连接数据库管理系统DBMS，然后通过DBMS操作数据库。</p></li><li><p>使用MySQL客户端，向数据库管理系统发送一条SQL语句，由数据库管理系统根据SQL语句指令去操作数据库中的表结构及数据。</p></li><li><p>一个数据库服务器中可以创建多个数据库，一个数据库中也可以包含多张表，而一张表中又可以包含多行记录。</p></li></ul><p>在Mysql数据库服务器当中存储数据，你需要：</p><ol><li><p>先去创建数据库（可以创建多个数据库，之间是相互独立的）</p></li><li><p>在数据库下再去创建数据表（一个数据库下可以创建多张表）</p></li><li><p>再将数据存放在数据表中（一张表可以存储多行数据）</p></li></ol>`,44)]])}var g=r(m,[[`render`,h]]);export{p as __pageData,g as default};